export function evaluate({ inputs, time }) {
  const launchSpeed = Number(inputs.launchSpeed ?? 4);
  const g = 9.8;
  const apexTime = launchSpeed / g;
  const apexHeight = (launchSpeed * launchSpeed) / (2 * g);
  const duration = (2 * launchSpeed) / g;
  const t = Math.max(0, Math.min(time, duration));
  const vel = launchSpeed - g * t;
  const h = launchSpeed * t - 0.5 * g * t * t;
  const y0 = 340;
  const pxPerM = 160;
  const xBall = 320;
  const yBall = y0 - h * pxPerM;
  const objects = [];
  const axisY = sdk.axis('axis.height', { x: 120, y: y0, length: 280, orientation: 'y', min: 0, max: 1.5, ticks: [0, 0.5, 1.0, 1.5], label: 'Height', unit: 'm' });
  objects.push(axisY);
  const guideLine = sdk.line('guide.launch', 120, y0, 480, y0, { role: 'neutral', opacity: 0.5 });
  const guideText = sdk.text('label.launch', 485, y0 + 4, 'Launch height', { align: 'start', role: 'neutral' });
  objects.push(guideLine, guideText);
  const ball = sdk.circle('ball.toss', xBall, yBall, 28, { role: 'learner' });
  objects.push(ball);
  const vScale = 18;
  const vVec = sdk.vector('vec.v', { x: xBall + 24, y: yBall }, { value: vel, direction: 'up', scale: vScale, label: 'v' });
  objects.push(...vVec);
  const aVec = sdk.vector('vec.a', { x: xBall - 24, y: yBall }, { value: -g, direction: 'up', scale: 4, label: 'a' });
  objects.push(...aVec);
  let line1 = 'Moving up';
  if (Math.abs(vel) < 0.05) {
    line1 = 'Still for an instant';
  } else if (vel < 0) {
    line1 = 'Moving down';
  }
  const calloutObjs = sdk.callout(xBall + 60, yBall - 10, [line1, 'Gravity pulls down'], { id: 'callout.toss' });
  objects.push(...calloutObjs);
  let motionStateIndex = 0;
  if (Math.abs(vel) < 0.05) {
    motionStateIndex = 1;
  } else if (vel < 0) {
    motionStateIndex = 2;
  }
  const frame = sdk.frame(objects);
  frame.readouts = [
    { id: 'motionState', value: motionStateIndex },
    { id: 'gravityState', value: 0 }
  ];
  return {
    frame,
    quantities: {
      launchSpeed,
      gravity: g,
      apexTime,
      apexHeight,
      velocity: vel,
      height: Math.max(0, h)
    }
  };
}
